import {Trace} from './trace.mjs';
function writeChar(){const b=new Trace('write-char','ft_putchar · a char argument and its address','The caller copies one char into a parameter. write receives the address of that char and a byte count.',`#include <unistd.h>\nvoid ft_putchar(char c)\n{\n    write(1, &c, 1);\n}\nint main(void)\n{\n    char letter = 'Z';\n    ft_putchar(letter);\n    ft_putchar('\n');\n    return (0);\n}`.replace("ft_putchar('\n');","ft_putchar('\\n');"));b.step("char letter = 'Z';",'Create the caller char','Store Z in letter.','The caller variable is independent of a function’s parameter copy.','Z → letter',()=>b.cell('letter','letter','char',0x1000,'Z'));b.step('ft_putchar(letter);','Pass the char by value','Read letter and copy Z into c.','This argument is a char value, not &letter.','letter value → local c',()=>{b.enter('ft_putchar');b.cell('c','c','char',0x2000,'Z');},['letter']);b.step('write(1, &c, 1);','Send one byte to stdout','write uses descriptor 1 (standard output), the address of c, and count 1.','&c identifies the source memory byte. write reads it; it does not change c.','&c → one byte → stdout',()=>b.state.output+='Z',['c']);b.step('}','Return from ft_putchar','The local char parameter leaves scope.','letter remains Z in main.','return → main',()=>b.leave());b.step("ft_putchar('\\n');",'Call with a newline char','Copy a newline into a new local c.','This extra newline belongs to the teaching main, not the ft_putchar contract.','newline value → c',()=>{b.enter('ft_putchar');b.cell('c','c','char',0x2000,'\\n');});b.step('write(1, &c, 1);','Write the newline byte','Read the current c and append a newline.','One byte is written per call.','c → stdout',()=>b.state.output+='\n',['c']);b.step('}','Return again','The second c parameter leaves scope.','The caller’s letter was never modified.','return → main',()=>b.leave());return b.finish('return (0);','');}
function predicate(){const code=`#include <stdio.h>\nint positive(int value)\n{\n    return (value > 0);\n}\nint main(void)\n{\n    int tab[3] = {-1, 2, 0};\n    int (*test)(int) = positive;\n    int count = 0;\n    int i = 0;\n    int accepted;\n    while (i < 3)\n    {\n        accepted = test(tab[i]);\n        if (accepted)\n            count++;\n        i++;\n    }\n    printf("%d\\n", count);\n    return (0);\n}`;const b=new Trace('predicate','Predicates · callback result controls a count','A predicate returns true or false; its caller decides whether to count or stop.',code);b.step('int tab[3] = {-1, 2, 0};','Create three inputs','Store -1, 2, and 0.','This example includes accepted and rejected values.','values → array',()=>b.ints('t',[-1,2,0],0x1000,'tab'));b.step('int (*test)(int) = positive;','Choose the predicate callback','Store positive’s function address in test.','The algorithm can use another compatible predicate without changing the loop.','function address → test',()=>{b.cell('function','positive','function',0xF000,'int → true/false','code');b.ptr('test','test','int (*)(int)',0x2000,'function');});for(const [id,loc]of [['count',0x2008],['i',0x200C]])b.step(`int ${id} = 0;`,'Initialize '+id,'Store zero.','count counts successes; i controls visitation.','0 → '+id,()=>b.cell(id,id,'int',loc,0));b.step('int accepted;','Reserve a result variable','Create accepted without an initial value.','Every loop iteration assigns it before the if reads it.','accepted created',()=>b.cell('accepted','accepted','int',0x2010,undefined));for(let i=0;i<3;i++){const val=[-1,2,0][i],ok=val>0;b.step('while (i < 3)','Check the array boundary',`${i} < 3 is true.`,'No out-of-range element is passed to the predicate.','true → callback',()=>{},['i']);b.step('accepted = test(tab[i]);','Call the predicate',`Copy ${val} into the callback’s value parameter.`,'Only the argument value is copied; the array element stays unchanged.','array value → callback parameter',()=>{b.enter('positive');b.cell('value','value','int',0x3000,val);},['test','t'+i]);b.step('return (value > 0);','Return a Boolean result',`${val} > 0 yields ${ok?1:0}.`,'C represents false as zero. This comparison yields 1 for true.','comparison → returned int',()=>{},['value']);b.leave();b.step('accepted = test(tab[i]);','Receive the predicate result',`Store returned ${ok?1:0} in accepted.`,'The callback parameter no longer exists.','result → accepted',()=>b.set('accepted',ok?1:0));b.step('if (accepted)','Decide whether to count',`accepted is ${ok?1:0}, so ${ok?'execute':'skip'} count++.`,'An any-style algorithm could stop after the first success; a count-style algorithm visits all values.','predicate result → branch',()=>{},['accepted']);if(ok)b.step('count++;','Count one success','Increase count to 1.','Only input 2 is positive in this example.','count + 1 → count',()=>b.set('count',1));b.step('i++;','Advance the input index',`Set i to ${i+1}.`,'The loop continues regardless of the predicate’s result.','i + 1 → i',()=>b.set('i',i+1));}b.step('while (i < 3)','Finish the scan','3 < 3 is false.','Exactly one input passed the predicate.','false → output',()=>{},['i']);return b.finish('printf("%d\\n", count);','1\n');}
function capitalize(){const code=`#include <stdio.h>\nint main(void)\n{\n    char text[] = "a b";\n    int first = 1;\n    int i = 0;\n    while (text[i] != '\\0')\n    {\n        if (text[i] == ' ')\n            first = 1;\n        else\n        {\n            if (first && text[i] >= 'a' && text[i] <= 'z')\n                text[i] = text[i] - 'a' + 'A';\n            first = 0;\n        }\n        i++;\n    }\n    printf("%s\\n", text);\n    return (0);\n}`;const b=new Trace('capitalize','Word state · capitalize first letters','Carry a small state flag across characters to recognize word beginnings.',code);b.step('char text[] = "a b";','Create two words','Initialize a, space, b, and zero.','This small example isolates the first-letter flag. The assignment also covers all non-alphanumeric separators and normalization of later letters.','chars → text',()=>b.chars('t','a b',0x1000,'text'));b.step('int first = 1;','Begin at a word boundary','Set first to 1.','The beginning of the whole string counts as a word start.','1 → first',()=>b.cell('first','first','int',0x2000,1));b.step('int i = 0;','Initialize the position','Set i to zero.','Each character can update the state for the next character.','0 → i',()=>b.cell('i','i','int',0x2004,0));for(let i=0;i<3;i++){b.step("while (text[i] != '\\0')",'Check the terminator','The current char is nonzero.','Visit this char before advancing.','true → body',()=>{},['t'+i]);const space=i===1;b.step("if (text[i] == ' ')",'Check the separator',`The current character ${space?'is':'is not'} a space.`,'A separator prepares the next letter to be a word start.','separator test → '+space,()=>{},['t'+i]);if(space)b.step('first = 1;','Mark a new word boundary','Store 1 in first.','The next letter can be capitalized.','1 → first',()=>b.set('first',1));else{b.step("if (first && text[i] >= 'a' && text[i] <= 'z')",'Check for a first lowercase letter','first is true and this letter is lowercase.','The flag connects this character to the earlier boundary.','first lowercase → true',()=>{},['first','t'+i]);b.step("text[i] = text[i] - 'a' + 'A';",'Capitalize this letter','Convert the lowercase letter to uppercase.','The writable char cell is modified in place. This formula uses the basic Latin character set.','lowercase char → uppercase char',()=>b.set('t'+i,i===0?'A':'B'),['t'+i]);b.step('first = 0;','Leave the word start','Set first to zero.','Later letters in this word are no longer first.','0 → first',()=>b.set('first',0));}b.step('i++;','Move to the next character',`Set i to ${i+1}.`,'The current state flag survives this update.','i + 1 → i',()=>b.set('i',i+1));}b.step("while (text[i] != '\\0')",'Finish at zero','The terminator ends the loop.','The result is A B.','false → output',()=>{},['t3']);return b.finish('printf("%s\\n", text);','A B\n');}
export function buildExtraSimulations(){return [writeChar(),predicate(),capitalize()];}
